old='''/**
 * Upsert by (org, kind, subject) rather than by row id: the indexer is called
 * on every write and must be idempotent.
 */'''
new='''/** Bound on the ids bound into one `IN (...)` list. */
const DELETE_CHUNK = 500;

/**
 * Upsert by (org, kind, subject) rather than by row id: the indexer is called
 * on every write and must be idempotent. Any duplicate rows left behind by
 * earlier drift are collapsed onto the one that is kept.
 */'''
assert old in s; s=s.replace(old,new)
old='''  const existing = db
    .select({ id: searchIndex.id })
    .from(searchIndex)
    .where(
      and(
        orgPredicate(searchIndex.orgId, orgId),
        eq(searchIndex.subjectKind, subjectKind),
        eq(searchIndex.subjectId, subjectId),
      ),
    )
    .get();

  if (existing) {
    db.update(searchIndex)
      .set({ content, projectId, indexedAt })
      .where(eq(searchIndex.id, existing.id))
      .run();
    return;
  }
'''
new='''  const [existing, ...duplicates] = db
    .select({ id: searchIndex.id })
    .from(searchIndex)
    .where(
      and(
        orgPredicate(searchIndex.orgId, orgId),
        eq(searchIndex.subjectKind, subjectKind),
        eq(searchIndex.subjectId, subjectId),
      ),
    )
    .all();

  if (existing) {
    db.update(searchIndex)
      .set({ content, projectId, indexedAt })
      .where(eq(searchIndex.id, existing.id))
      .run();
    if (duplicates.length > 0) {
      db.delete(searchIndex)
        .where(
          and(
            orgPredicate(searchIndex.orgId, orgId),
            inArray(
              searchIndex.id,
              duplicates.map((row) => row.id),
            ),
          ),
        )
        .run();
    }
    return;
  }
'''
assert old in s; s=s.replace(old,new)
old='''/**
 * Substring match over the denormalised content column.'''
new='''/** Bulk form of `deleteSearchDocument`, e.g. for every comment on one issue. */
export async function deleteSearchDocuments(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectIds: readonly string[],
): Promise<void> {
  const db = getDb();
  for (let at = 0; at < subjectIds.length; at += DELETE_CHUNK) {
    db.delete(searchIndex)
      .where(
        and(
          orgPredicate(searchIndex.orgId, orgId),
          eq(searchIndex.subjectKind, subjectKind),
          inArray(searchIndex.subjectId, [
            ...subjectIds.slice(at, at + DELETE_CHUNK),
          ]),
        ),
      )
      .run();
  }
}

/** Every subject this org currently has a document for; the rebuild prunes against it. */
export async function listIndexedSubjects(
  orgId: OrgId,
): Promise<
  readonly { subjectKind: SearchSubjectKind; subjectId: string }[]
> {
  return getDb()
    .selectDistinct({
      subjectKind: searchIndex.subjectKind,
      subjectId: searchIndex.subjectId,
    })
    .from(searchIndex)
    .where(orgPredicate(searchIndex.orgId, orgId))
    .all();
}

/**
 * Substring match over the denormalised content column.'''
assert old in s; s=s.replace(old,new)
open(p,'w').write(s)
EOF

