import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("~t/server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("~t/server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("~t/server/_support/doubles/misc")).rateLimitModule);

import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as searchService from "@/server/services/search-service";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { runSearchReindexJob } from "@/server/jobs/search-reindex-job";
import { createTenant, issueInput, useTemporaryDatabase } from "~t/server/_support/fixtures";

let cleanup: () => void;
let detach: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); detach = searchService.registerSearchListeners(); });
afterAll(() => { detach(); cleanup(); });

const q = (t: any, text: string, kinds: any[] = []) => searchService.search(t.actors.member, { orgId: t.org.id, q: text, kinds, limit: 100, cursor: null });
const comment = (t: any, issueId: any, body: string, parentId: any = null) => commentService.createComment(t.actors.member, { orgId: t.org.id, issueId, body, parentId, mentionedUserIds: [] });

describe("scratch", () => {
  it("all scenarios", async () => {
    const a = await createTenant("aaa", "growth");
    const b = await createTenant("bbb", "growth");
    const i1 = await issueService.createIssue(a.actors.member, issueInput(a.org.id, a.project.id, { title: "IssueOne" }));
    const c1 = await comment(a, i1.id, "ParentMarker");
    const r1 = await comment(a, i1.id, "ReplyMarker", c1.id);
    const c2 = await comment(a, i1.id, "OtherMarker");
    await commentService.deleteComment(a.actors.member, { orgId: a.org.id, commentId: c1.id });
    expect((await issueService.getIssue(a.actors.member, a.org.id, i1.id)).commentCount).toBe(2);
    expect((await q(a, "ParentMarker")).total).toBe(0);
    expect((await q(a, "ReplyMarker")).total).toBe(1);
    expect((await q(a, "IssueOne")).total).toBe(1);

    const i2 = await issueService.createIssue(a.actors.member, issueInput(a.org.id, a.project.id, { title: "IssueTwo" }));
    const c3 = await comment(a, i2.id, "ArchThreadMarker");
    await comment(a, i2.id, "ArchThreadMarker reply", c3.id);
    const bi = await issueService.createIssue(b.actors.member, issueInput(b.org.id, b.project.id, { title: "BIssue" }));
    await comment(b, bi.id, "ArchThreadMarker in b");
    await issueService.archiveIssue(a.actors.member, a.org.id, i2.id);
    expect((await q(a, "ArchThreadMarker")).total).toBe(0);
    expect((await q(a, "IssueTwo")).total).toBe(0);
    expect((await q(b, "ArchThreadMarker")).total).toBe(1);
    expect((await q(a, "OtherMarker")).total).toBe(1);

    // bulk: many issues and a long thread
    for (let n = 0; n < 130; n++) await issueRepo.insertIssue(issueInput(a.org.id, a.project.id, { title: `Bulk${String(n).padStart(3, "0")}` }) as any, a.userIds.member, 100 + n);
    for (let n = 0; n < 150; n++) await commentRepo.insertComment({ orgId: a.org.id, issueId: i1.id, body: `Long${String(n).padStart(3, "0")}`, parentId: null, mentionedUserIds: [] } as any, a.userIds.member);

    const r = await runSearchReindexJob(a.org.id);
    await runSearchReindexJob(a.org.id);
    expect(r.failed).toBe(0);
    expect((await q(a, "ParentMarker")).total).toBe(0);
    expect((await q(a, "ReplyMarker")).total).toBe(1);
    expect((await q(a, "ArchThreadMarker")).total).toBe(0);
    expect((await q(a, "IssueTwo")).total).toBe(0);
    expect((await q(a, "Bulk000")).total).toBe(1);
    expect((await q(a, "Bulk", ["issue"])).total).toBe(130);
    expect((await q(a, "Long000")).total).toBe(1);
    expect((await q(a, "Long", ["comment"])).total).toBe(150);
    expect((await q(a, "IssueOne")).total).toBe(1);
    expect((await q(b, "ArchThreadMarker")).total).toBe(1);
    expect((await q(b, "BIssue")).total).toBe(1);
    // processed = projects + issues + live comments
    expect(r.processed).toBe(1 + 131 + 2 + 150);
  });
});
