  it("drops docs that bypassed listeners", async () => {
    const t = await createTenant("ccc", "growth");
    const i = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "PruneIssue" }));
    const c = await commentRepo.insertComment({ orgId: t.org.id, issueId: i.id, body: "PruneStale", parentId: null, mentionedUserIds: [] } as any, t.userIds.member);
    await searchService.indexComment(t.org.id, c);
    await commentRepo.archiveComment(t.org.id, c.id);
    const i2 = await issueRepo.insertIssue(issueInput(t.org.id, t.project.id, { title: "PruneArchivedIssue" }) as any, t.userIds.member, 99);
    await searchService.indexIssue(t.org.id, i2);
    await issueRepo.archiveIssue(t.org.id, i2.id);
    expect((await q(t, "Prune")).total).toBe(3);
    await runSearchReindexJob(t.org.id);
    const hits = await q(t, "Prune");
    expect(hits.items.map((h) => h.id)).toEqual([i.id]);
  });
});
